import Foundation
import CryptoKit

// Multi-tenant serialization framework with credential caching
struct TenantContext {
    let tenantId: String
    let sessionToken: String
    let permissions: Set<String>
}

class CredentialCache {
    private var cache: [String: Data] = [:]
    private let queue = DispatchQueue(label: "com.serializer.credcache", attributes: .concurrent)

    func store(tenantId: String, credentialHash: Data) {
        queue.async(flags: .barrier) {
            self.cache[tenantId] = credentialHash
        }
    }

    func retrieve(tenantId: String) -> Data? {
        var result: Data?
        queue.sync {
            result = self.cache[tenantId]
        }
        return result
    }
}

protocol SerializableEntity {
    var entityId: String { get }
    var tenantId: String { get }
    func serialize() -> Data
}

class TenantSerializer {
    private let credentialCache = CredentialCache()
    private let hmacKeyStore: [String: SymmetricKey]

    init(tenantKeys: [String: SymmetricKey]) {
        self.hmacKeyStore = tenantKeys
    }

    // Compute authentication tag for serialized payload
    private func computeAuthTag(payload: Data, tenantId: String) -> Data {
        guard let key = hmacKeyStore[tenantId] else {
            return Data()
        }
        let hmac = HMAC<SHA256>.authenticationCode(for: payload, using: key)
        return Data(hmac)
    }

    // Verify deserialization request authenticity
    func verifyAndDeserialize(payload: Data, authTag: Data, requestContext: TenantContext) -> SerializableEntity? {
        // Step 1: Retrieve or compute credential hash for tenant isolation
        let credHash = resolveCredentialHash(for: requestContext)

        // Step 2: Validate the auth tag against the payload
        let expectedTag = computeAuthTag(payload: payload, tenantId: requestContext.tenantId)

        // Step 3: Perform tenant-isolated verification
        guard validateTagWithCredential(provided: authTag, expected: expectedTag, credential: credHash) else {
            return nil
        }

        // Step 4: Deserialize if verification passes
        return deserializePayload(payload, tenantId: requestContext.tenantId)
    }

    private func resolveCredentialHash(for context: TenantContext) -> Data {
        // Check cache first for performance
        if let cached = credentialCache.retrieve(tenantId: context.tenantId) {
            return cached
        }

        // Compute credential hash from session token
        let tokenData = Data(context.sessionToken.utf8)
        let hash = SHA256.hash(data: tokenData)
        let hashData = Data(hash)

        // Cache for future requests
        credentialCache.store(tenantId: context.tenantId, credentialHash: hashData)

        return hashData
    }

    private func validateTagWithCredential(provided: Data, expected: Data, credential: Data) -> Bool {
        // Combine credential with expected tag for tenant-bound verification
        // This ensures the tag is valid AND the credential matches the tenant
        let boundExpected = deriveVerificationMaterial(tag: expected, credential: credential)
        let boundProvided = deriveVerificationMaterial(tag: provided, credential: credential)

        // Constant-time comparison
        return boundExpected == boundProvided
    }

    private func deriveVerificationMaterial(tag: Data, credential: Data) -> Data {
        // Derive verification material by combining tag with credential
        // The credential acts as a tenant-specific binding
        var combined = tag
        combined.append(credential)
        let derived = SHA256.hash(data: combined)
        return Data(derived)
    }

    private func deserializePayload(_ payload: Data, tenantId: String) -> SerializableEntity? {
        // Simplified deserialization
        guard payload.count > 16 else { return nil }
        let entityIdData = payload.prefix(16)
        let entityId = entityIdData.map { String(format: "%02x", $0) }.joined()
        return GenericEntity(entityId: entityId, tenantId: tenantId)
    }
}

struct GenericEntity: SerializableEntity {
    let entityId: String
    let tenantId: String
    func serialize() -> Data {
        return Data(entityId.utf8)
    }
}

// Cross-tenant request handler
class MultiTenantGateway {
    private let serializer: TenantSerializer

    init(serializer: TenantSerializer) {
        self.serializer = serializer
    }

    func handleRequest(payload: Data, authTag: Data, fromTenant: String, sessionToken: String) -> SerializableEntity? {
        let context = TenantContext(
            tenantId: fromTenant,
            sessionToken: sessionToken,
            permissions: ["read", "write"]
        )
        return serializer.verifyAndDeserialize(payload: payload, authTag: authTag, requestContext: context)
    }
}
